    /** 尽量保留的字段（§3.5.3 推荐 + 网页版实际字段，按重要性排序） */
    private val KEEP_KEYS = setOf(
        // 路径 A：fast login 核心
        "Os_SSo_Sid", "RMKEY", "UserData", "Login_UserNumber",
        "_139_index_isLoginType", "UUIDToken", "JSESSIONID",
