package com.xingchen.desktop

import androidx.compose.runtime.*
import com.yunx.app.data.network.*
import com.yunx.app.data.network.model.*
import kotlinx.coroutines.*
import org.json.JSONArray
import org.json.JSONObject

class DesktopModel(val store: Store, val scope: CoroutineScope) {
    val drives=DriveService(store)
    val downloads=Downloads(store,scope)
    var page by mutableStateOf("解析")
    var input by mutableStateOf("")
    var platform by mutableStateOf(SharePlatform.QUARK)
    var files by mutableStateOf<List<ShareFile>>(emptyList())
    var session by mutableStateOf<ShareSession?>(null)
    var cloudMode by mutableStateOf(false)
    var busy by mutableStateOf(false)
    var message by mutableStateOf("")
    var dir by mutableStateOf("0")
    var title by mutableStateOf("")
    var selected by mutableStateOf<Set<String>>(emptySet())
    var recent by mutableStateOf<List<JSONObject>>(emptyList())
    var accounts by mutableStateOf<Map<SharePlatform,String>>(emptyMap())
    var settingRevision by mutableStateOf(0)
    private var stack=ArrayDeque<Pair<String,String>>()
    init {
        loadRecent()
        downloads.sourceRefresh = { task ->
            val source=JSONObject(task.source);val p=SharePlatform.valueOf(task.platform)
            val file=fileFromJson(source.getJSONObject("file"))
            val link=if(source.optBoolean("cloud")) drives.cloudLink(p,file) else {
                val s=source.getJSONObject("session")
                drives.refreshCredential(p)
                drives.repository(p).getShareDownloadLink(ShareSession(s.getString("id"),s.getString("token"),s.getString("title")),file,drives.credential(p)).getOrThrow()
            }
            link to drives.headers(p)
        }
        downloads.onCompleted = { task ->
            WindowsNative.notifyCompleted(task.name)
            val cleanup = runCatching { JSONObject(task.source).optString("cleanupDir") }.getOrDefault("")
            if (cleanup.isNotBlank()) {
                val p = SharePlatform.valueOf(task.platform)
                runCatching { drives.repository(p).cleanupTempDir(cleanup, drives.credential(p)) }
            }
        }
    }
    fun loadRecent() {
        val list=store.data.optJSONArray("recent") ?: JSONArray()
        recent=(0 until list.length()).map { list.getJSONObject(it) }
    }
    fun saveRecent(list: List<JSONObject>) { recent=list;store.data.put("recent",JSONArray(list));store.save() }
    fun action(block: suspend ()->Unit) {
        if(busy) return
        scope.launch {
            busy=true;message=""
            try { block() }
            catch(e: CancellationException) { throw e }
            catch(_: Exception) { message="操作失败，请检查认证、提取码、网络或平台限制后重试" }
            finally { busy=false }
        }
    }
    fun resolve(link: String = input) = action {
        val parsed=ShareLinkParser.parse(link) ?: error("无法识别链接")
        platform=parsed.platform;cloudMode=false;session=null;files=emptyList();selected=emptySet();stack.clear()
        val record=JSONObject().put("link",link).put("platform",platform.name).put("time",System.currentTimeMillis()).put("title",parsed.shareId).put("status","解析中")
        saveRecent((listOf(record)+recent.filterNot { it.optString("link")==link }).take(100))
        try {
            drives.refreshCredential(platform)
            val s=drives.repository(platform).createSession(link,parsed.pwd,drives.credential(platform)).getOrThrow()
            val result=drives.repository(platform).listFiles(s,drives.root(platform),drives.credential(platform)).getOrThrow()
            session=s;dir=drives.root(platform);title=s.title;files=result;page="解析"
            record.put("title",s.title).put("status","成功");saveRecent(recent)
        } catch(e: Exception) {
            record.put("status","失败");saveRecent(recent);throw e
        }
    }
    fun openCloud(p: SharePlatform = platform) = action {
        platform=p;cloudMode=true;session=null;stack.clear();dir=drives.root(p);title=platformName(p)
        files=emptyList();selected=emptySet();files=drives.cloud(p,dir)
    }
    private suspend fun list(directory: String) = if(cloudMode) drives.cloud(platform,directory)
        else drives.repository(platform).listFiles(session ?: error("请重新解析"),directory,drives.credential(platform)).getOrThrow()
    fun folder(file: ShareFile) = action {
        val next=if(platform==SharePlatform.BAIDU && cloudMode) file.fid else file.fid
        val result=list(next);stack.addLast(dir to title);dir=next;title=file.fname;files=result;selected=emptySet()
    }
    fun up() = action {
        if(stack.isNotEmpty()) { val target=stack.last();val result=list(target.first);stack.removeLast();dir=target.first;title=target.second;files=result;selected=emptySet() }
    }
    fun refreshFiles() = action { files=list(dir);selected=emptySet() }
    fun download(items: List<ShareFile>) = action {
        val p=platform;val s=session;val cloud=cloudMode
        suspend fun add(file: ShareFile, depth: Int) {
            require(depth<=12) { "文件夹层数过深" }
            if(file.isdir) {
                val nested=if(cloud) drives.cloud(p,file.fid) else drives.repository(p).listFiles(s!!,file.fid,drives.credential(p)).getOrThrow()
                nested.forEach { add(it,depth+1) };return
            }
            drives.refreshCredential(p)
            val link=if(cloud) drives.cloudLink(p,file) else drives.repository(p).getShareDownloadLink(s!!,file,drives.credential(p)).getOrThrow()
            val source=JSONObject().put("cloud",cloud).put("file",fileToJson(file)).put("cleanupDir",link.cleanupDirFid.orEmpty())
            if(s!=null) source.put("session",JSONObject().put("id",s.shareId).put("token",s.stoken).put("title",s.title))
            downloads.enqueue(link,drives.headers(p),p.name,source.toString())
        }
        items.forEach { add(it,0) };message="已加入下载队列";selected=emptySet()
    }
    fun saveShare(file: ShareFile) = action {
        val s=session ?: error("请先解析分享")
        drives.repository(platform).transferFile(s,file,drives.root(platform),drives.credential(platform)).getOrThrow()
        message="已保存到网盘根目录"
    }
    fun checkAccount(p: SharePlatform) = action {
        accounts=accounts+(p to "验证中")
        val status=try { drives.accountStatus(p) } catch(_: Exception) { "未验证 / 认证失效 / 网络不可用" }
        accounts=accounts+(p to status)
    }
    fun accountSave(p: SharePlatform, text: String) = action {
        // Raw Cookie/Token or Android-compatible account JSON including optional refresh/device/captcha fields.
        val account=if(text.trim().startsWith("{")) JSONObject(text) else JSONObject().put("credential",text.trim().removePrefix("Bearer "))
        if(!account.has("credential")) account.put("credential",account.optString("cookie").ifBlank { account.optString("accessToken") })
        require(account.optString("credential").isNotBlank())
        store.credentials().put(p.name,account);store.save()
        accounts=accounts+(p to try { drives.accountStatus(p) } catch(_: Exception) { "已导入，验证失败" })
    }
    fun logout(p: SharePlatform) { store.credentials().remove(p.name);store.save();accounts=accounts+(p to "未登录") }
    fun setting(key: String, value: Any) { store.settings().put(key,value);store.save();settingRevision++ }
    companion object {
        fun fileToJson(f: ShareFile) = JSONObject().put("id",f.fid).put("name",f.fname).put("size",f.fsize).put("dir",f.isdir).put("parent",f.pdirFid).put("token",f.fidToken)
        fun fileFromJson(j: JSONObject) = ShareFile(j.getString("id"),j.getString("name"),j.getLong("size"),j.getBoolean("dir"),j.getString("parent"),j.getString("token"))
    }
}

package com.xingchen.desktop

import com.yunx.app.data.download.HlsDownloader
import com.yunx.app.data.network.HttpClients
import com.yunx.app.data.network.model.DownloadLink
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import okhttp3.Call
import okhttp3.Request
import org.json.JSONArray
import org.json.JSONObject
import java.io.IOException
import java.io.RandomAccessFile
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.StandardCopyOption
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap
import kotlin.math.max

class Downloads(private val store: Store, private val scope: CoroutineScope) {
    data class Task(val id: String, val name: String, val path: String, val platform: String,
                    val url: String, val headers: Map<String,String>, val total: Long,
                    val done: Long = 0, val speed: Long = 0, val status: String = "等待中",
                    val completed: Long = 0, val etag: String = "", val error: String = "",
                    val hls: Boolean = false, val source: String = "")
    private val mutable = MutableStateFlow<List<Task>>(emptyList())
    val tasks = mutable.asStateFlow()
    private val jobs = ConcurrentHashMap<String,Job>()
    private val calls = ConcurrentHashMap<String,Call>()
    var sourceRefresh: (suspend (Task) -> Pair<DownloadLink,Map<String,String>>)? = null
    var onCompleted: (suspend (Task) -> Unit)? = null
    init {
        val saved = store.data.optJSONArray("downloads") ?: JSONArray()
        mutable.value = (0 until saved.length()).map { decode(saved.getJSONObject(it)) }.map {
            if (it.status in listOf("下载中","等待中")) it.copy(status="已暂停",speed=0) else it
        }
    }
    @Synchronized private fun publish(list: List<Task>, persist: Boolean = true) {
        mutable.value = list
        if (persist) {
            store.data.put("downloads",JSONArray(list.map { encode(it) })); store.save()
        }
    }
    @Synchronized private fun update(id: String, persist: Boolean = true, action: (Task)->Task) = publish(mutable.value.map { if (it.id==id) action(it) else it },persist)
    fun get(id: String) = mutable.value.first { it.id == id }
    fun enqueue(link: DownloadLink, headers: Map<String,String>, platform: String, source: String = ""): String {
        val directory = Path.of(store.settings().optString("directory",Path.of(System.getProperty("user.home"),"Downloads","星辰助手").toString())).toAbsolutePath().normalize()
        Files.createDirectories(directory)
        val name = safeName(link.filename)
        var path = directory.resolve(name)
        val overwrite = store.settings().optBoolean("overwrite",false)
        var suffix = 1
        while (mutable.value.any { it.path == path.toString() && it.status != "已取消" } || (!overwrite && (Files.exists(path) || Files.exists(Path.of("$path.part"))))) {
            val ext = name.substringAfterLast('.',"");val base = if (ext.isBlank()) name else name.substringBeforeLast('.')
            path=directory.resolve("$base (${suffix++})" + if(ext.isBlank()) "" else ".$ext")
        }
        val task = Task(UUID.randomUUID().toString(),path.fileName.toString(),path.toString(),platform,link.downloadUrl,headers,link.size,hls=link.isHls,source=source)
        publish(mutable.value + task); schedule(); return task.id
    }
    @Synchronized fun resume(id: String) {
        if (jobs.containsKey(id)) return
        update(id) { it.copy(status="等待中",error="",speed=0) }; schedule()
    }
    @Synchronized private fun schedule() {
        val maxConcurrent = store.settings().optInt("concurrency",3).coerceIn(1,16)
        mutable.value.filter { it.status=="等待中" && !jobs.containsKey(it.id) }.take(max(0,maxConcurrent-jobs.size)).forEach { t ->
            val job = scope.launch(Dispatchers.IO, start=CoroutineStart.LAZY) {
                try { transfer(t.id) } finally { jobs.remove(t.id); schedule() }
            }
            jobs[t.id]=job;job.start()
        }
    }
    fun pause(id: String) {
        update(id) { it.copy(status="已暂停",speed=0) };calls[id]?.cancel();jobs[id]?.cancel()
    }
    fun cancel(id: String) {
        update(id) { it.copy(status="已取消",speed=0) };calls[id]?.cancel();jobs[id]?.cancel()
    }
    fun remove(id: String) {
        val job = jobs[id]
        if (job != null) {
            cancel(id)
            job.invokeOnCompletion { synchronized(this) { publish(mutable.value.filterNot { it.id==id }) } }
        } else publish(mutable.value.filterNot { it.id==id })
    }
    fun clearCompleted() = publish(mutable.value.filterNot { it.status=="已完成" })
    fun shutdown() {
        mutable.value.filter { it.status in listOf("下载中","等待中") }.forEach { pause(it.id) }
    }
    private suspend fun transfer(id: String) {
        update(id) { it.copy(status="下载中",error="") }
        val retries = store.settings().optInt("retries",3).coerceIn(0,20)
        var success = false
        var attempt = 0
        while (!success) {
            try {
                currentCoroutineContext().ensureActive()
                downloadOnce(id)
                success=true
            } catch(e: CancellationException) { throw e }
            catch(_: Exception) {
                currentCoroutineContext().ensureActive()
                if (attempt++ >= retries) {
                    update(id) { it.copy(status="失败",speed=0,error="下载失败：请检查认证、链接、网络和磁盘空间后重试") }; return
                }
                if (sourceRefresh != null && get(id).source.isNotBlank()) {
                    try {
                        val (link,headers)=sourceRefresh!!.invoke(get(id))
                        update(id) { it.copy(url=link.downloadUrl,headers=headers,total=link.size,hls=link.isHls) }
                    } catch(e: CancellationException) { throw e } catch(_: Exception) { /* bounded retry below */ }
                }
                delay(1000L * attempt)
            }
        }
        update(id) { it.copy(status="已完成",completed=System.currentTimeMillis(),speed=0) }
        onCompleted?.invoke(get(id))
    }
    private suspend fun downloadOnce(id: String) {
        val task=get(id);val partial=Path.of(task.path+".part")
        if (task.hls) {
            Files.deleteIfExists(partial)
            update(id) { it.copy(done=0,total=-1) }
            var count=0L
            val ok=HlsDownloader.download(task.url,task.headers,partial.toFile()) { n ->
                currentCoroutineContext().ensureActive(); count+=n
                update(id,false) { it.copy(done=count) }
            }
            currentCoroutineContext().ensureActive()
            if (!ok) throw IOException("HLS failed")
            update(id) { it.copy(done=count,total=count) }
        } else {
            var offset=if(Files.exists(partial)) Files.size(partial) else 0L
            val builder=Request.Builder().url(task.url)
            task.headers.forEach { (k,v) -> builder.header(k,v) }
            if(offset>0) {
                // A previous server must supply a validator before safe resumption.
                if (task.etag.isBlank()) { Files.deleteIfExists(partial);offset=0 }
                else builder.header("Range","bytes=$offset-").header("If-Range",task.etag)
            }
            val origin=builder.build().url
            val client=HttpClients.downloadClient().newBuilder().addNetworkInterceptor { chain ->
                var request=chain.request()
                if(request.url.scheme!=origin.scheme || request.url.host!=origin.host || request.url.port!=origin.port) {
                    request=request.newBuilder().removeHeader("Cookie").removeHeader("Authorization").removeHeader("Proxy-Authorization").removeHeader("Origin").removeHeader("Referer").build()
                }
                chain.proceed(request)
            }.build()
            val call=client.newCall(builder.build()); calls[id]=call
            val cancelHandle=currentCoroutineContext().job.invokeOnCompletion { call.cancel() }
            try { call.execute().use { response ->
                if (!response.isSuccessful) throw IOException("HTTP ${response.code}")
                val body=response.body ?: throw IOException("Empty body")
                val range=response.header("Content-Range").orEmpty()
                if (offset>0 && response.code==206 && !range.startsWith("bytes $offset-")) throw IOException("Invalid Range")
                if (response.code==206 && !range.startsWith("bytes $offset-")) throw IOException("Invalid Range")
                if (response.code==200) offset=0L
                val advertised=if(response.code==206) range.substringAfterLast('/').toLongOrNull() ?: -1L else body.contentLength()
                if(task.total>0 && advertised>0 && task.total!=advertised) throw IOException("Changed file size")
                val validator=response.header("ETag")?.takeUnless { it.startsWith("W/") } ?: response.header("Last-Modified").orEmpty()
                update(id) { it.copy(done=offset,total=if(advertised>0) advertised else task.total,etag=validator) }
                RandomAccessFile(partial.toFile(),"rw").use { output ->
                    output.setLength(offset);output.seek(offset)
                    body.byteStream().use { input ->
                        val buffer=ByteArray(64*1024);var done=offset;val started=System.nanoTime();var tick=started;var last=done
                        while(true) {
                            currentCoroutineContext().ensureActive()
                            val n=input.read(buffer);if(n<0) break
                            output.write(buffer,0,n);done+=n
                            val now=System.nanoTime()
                            if(now-tick>250_000_000) {
                                val speed=((done-last)*1_000_000_000/(now-tick)).coerceAtLeast(0)
                                update(id,false) { it.copy(done=done,speed=speed) };tick=now;last=done
                            }
                            val limit=store.settings().optLong("limitKB",0)*1024
                            if(limit>0) {
                                val expected=(done-offset)*1000/limit;val elapsed=(System.nanoTime()-started)/1_000_000
                                if(expected>elapsed) delay(expected-elapsed)
                            }
                        }
                        val total=get(id).total
                        if(total>0 && done!=total) throw IOException("Truncated download")
                        update(id) { it.copy(done=done,total=done) };output.fd.sync()
                    }
                }
            } } finally { calls.remove(id); cancelHandle.dispose() }
        }
        currentCoroutineContext().ensureActive()
        Files.move(partial,Path.of(task.path),StandardCopyOption.REPLACE_EXISTING)
    }
    companion object {
        fun safeName(raw: String): String {
            require(!raw.replace('\\','/').split('/').any { it==".." || it=="." }) { "无效文件名" }
            var name=raw.substringAfterLast('/').substringAfterLast('\\').replace(Regex("[<>:\"/\\\\|?*\\x00-\\x1f]"),"_").trim().trimEnd('.',' ')
            if(name.isBlank()) name="download"
            if(Regex("^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(\\..*)?$",RegexOption.IGNORE_CASE).matches(name)) name="_$name"
            return name.take(180)
        }
        fun encode(t: Task): JSONObject = JSONObject().put("id",t.id).put("name",t.name).put("path",t.path).put("platform",t.platform)
            .put("url",t.url).put("headers",JSONObject(t.headers)).put("total",t.total).put("done",t.done).put("status",t.status)
            .put("completed",t.completed).put("etag",t.etag).put("hls",t.hls).put("source",t.source)
        fun decode(j: JSONObject): Task {
            val headers=j.optJSONObject("headers") ?: JSONObject()
            return Task(j.getString("id"),j.getString("name"),j.getString("path"),j.getString("platform"),j.getString("url"),
                headers.keys().asSequence().associateWith { headers.getString(it) },j.optLong("total",-1),j.optLong("done"),status=j.getString("status"),
                completed=j.optLong("completed"),etag=j.optString("etag"),hls=j.optBoolean("hls"),source=j.optString("source"))
        }
    }
}

package com.xingchen.desktop

import com.yunx.app.data.network.*
import com.yunx.app.data.network.model.*
import com.yunx.app.data.repository.*
import org.json.JSONObject

class DriveService(private val store: Store) {
    val quark = QuarkApi()
    val uc = UCApi()
    val baidu = BaiduApi()
    val mobile = C139Api()
    val pan123 = Pan123Api()
    val xunlei = XunleiApi()
    init {
        quark.cookieSink = { cookie -> store.credentials().optJSONObject("QUARK")?.put("credential",cookie); store.save() }
        uc.cookieSink = { cookie -> store.credentials().optJSONObject("UC")?.put("credential",cookie); store.save() }
    }
    fun credential(p: SharePlatform) = store.credential(p.name)
    private fun account() = store.credentials().optJSONObject("XUNLEI") ?: JSONObject()
    fun deviceId() = account().optString("deviceId").ifBlank { XunleiDeviceFingerprint.deviceId() }
    fun captcha() = account().optString("captchaToken")
    private val repositories: Map<SharePlatform,ShareResolveRepository> = mapOf(
        SharePlatform.QUARK to QuarkResolveRepository(quark),
        SharePlatform.UC to UCResolveRepository(uc),
        SharePlatform.BAIDU to BaiduResolveRepository(baidu),
        SharePlatform.C139 to C139ResolveRepository(mobile),
        SharePlatform.PAN123 to Pan123ResolveRepository(pan123) { credential(SharePlatform.PAN123) },
        SharePlatform.XUNLEI to XunleiResolveRepository(xunlei,
            { credential(SharePlatform.XUNLEI).takeIf { it.isNotBlank() } }, { deviceId() }, { captcha() }, {
                val refresh = account().optString("refreshToken")
                if (refresh.isBlank()) null else xunlei.refreshToken(refresh, deviceId())?.also { (access, next) ->
                    account().put("credential", access).put("refreshToken", next); store.save()
                }
            })
    )
    fun repository(p: SharePlatform) = repositories.getValue(p)
    fun root(p: SharePlatform) = if (p == SharePlatform.BAIDU) "/" else "0"
    suspend fun refreshCredential(p: SharePlatform): String {
        val original = credential(p)
        val fresh = when(p) {
            SharePlatform.QUARK -> quark.refreshSession(original)
            SharePlatform.UC -> uc.refreshSession(original)
            else -> null
        }
        if (!fresh.isNullOrBlank()) { store.credentials().getJSONObject(p.name).put("credential",fresh); store.save() }
        return fresh ?: original
    }
    suspend fun accountStatus(p: SharePlatform): String {
        val c = credential(p)
        require(c.isNotBlank()) { "未登录" }
        val quota = when(p) {
            SharePlatform.QUARK -> quark.getQuota(c)
            SharePlatform.UC -> uc.getQuota(c)
            SharePlatform.BAIDU -> baidu.getQuota(c)
            SharePlatform.C139 -> mobile.getQuota(c)
            SharePlatform.PAN123 -> pan123.getQuota(c)
            SharePlatform.XUNLEI -> xunlei.getQuota(c,deviceId(),captcha())
        } ?: error("认证失效或网络不可用，请重新验证")
        return "已登录 · ${bytes(quota.used)} / ${bytes(quota.total)}"
    }
    suspend fun cloud(p: SharePlatform, dir: String): List<ShareFile> {
        val c = refreshCredential(p)
        require(c.isNotBlank()) { "请先在账号页导入认证" }
        return when(p) {
            SharePlatform.QUARK -> quark.listCloudFiles(dir,c) ?: error("获取文件失败")
            SharePlatform.UC -> uc.listCloudFiles(dir,c) ?: error("获取文件失败")
            SharePlatform.BAIDU -> baidu.listCloudFiles(dir,c)
            SharePlatform.C139 -> mobile.listCloudFiles(dir,c)
            SharePlatform.PAN123 -> pan123.listCloudFiles(dir,c)
            SharePlatform.XUNLEI -> xunlei.getFiles(dir,c,deviceId(),captcha()) ?: emptyList()
        }
    }
    suspend fun cloudLink(p: SharePlatform, file: ShareFile): DownloadLink {
        val c = refreshCredential(p)
        return when(p) {
            SharePlatform.QUARK -> quark.getDownloadLink(file.fid,c)
            SharePlatform.UC -> uc.cloudGetDownloadLink(file.fid,c)
            SharePlatform.BAIDU -> DownloadLink(file.fid,file.fname,baidu.fileMetasDlink(file.fid,c),file.fsize)
            SharePlatform.C139 -> mobile.getDownloadUrl(file.fid,c)
            SharePlatform.PAN123 -> pan123.getDownloadLink(file,c)
            SharePlatform.XUNLEI -> xunlei.getFileDetail(file.fid,c,deviceId(),captcha())
        } ?: error("获取下载地址失败")
    }
    fun headers(p: SharePlatform): Map<String,String> = when(p) {
        SharePlatform.QUARK -> mapOf("Cookie" to credential(p), "User-Agent" to QuarkConstants.API_USER_AGENT, "Referer" to QuarkConstants.DOWNLOAD_REFERER)
        SharePlatform.UC -> mapOf("Cookie" to credential(p), "User-Agent" to UCConstants.USER_AGENT, "Referer" to UCConstants.DOWNLOAD_REFERER, "Origin" to UCConstants.WEB_ORIGIN)
        SharePlatform.BAIDU -> mapOf("Cookie" to credential(p), "User-Agent" to BaiduConstants.UA_NETDISK)
        SharePlatform.C139 -> mapOf("User-Agent" to C139Constants.PC_UA)
        SharePlatform.PAN123 -> mapOf("User-Agent" to Pan123Constants.WEB_UA, "Referer" to Pan123Constants.DOWNLOAD_REFERER)
        SharePlatform.XUNLEI -> mapOf("User-Agent" to XunleiConstants.APP_UA)
    }
}
fun platformName(p: SharePlatform) = when(p) {
    SharePlatform.QUARK -> "夸克"; SharePlatform.UC -> "UC"; SharePlatform.XUNLEI -> "迅雷"
    SharePlatform.BAIDU -> "百度网盘"; SharePlatform.PAN123 -> "123云盘"; SharePlatform.C139 -> "移动云盘"
}
fun bytes(n: Long): String = when {
    n < 0 -> "未知"; n < 1024 -> "$n B"; n < 1048576 -> "%.1f KB".format(n/1024.0)
    n < 1073741824 -> "%.1f MB".format(n/1048576.0); else -> "%.2f GB".format(n/1073741824.0)
}

